console.log("[Design] Y stepper UI fill did not propagate, updating v through DesignStore");
const designStoreResult = await page.evaluate(
  ({ guids, value }: { guids: string[]; value: number }) => {
    const store = (window as any).__SEMIO_STORE__;
    if (!store) return { error: "no store" };
    const kitGuids = Array.from((store as any).kits?.keys() ?? []) as string[];
    if (kitGuids.length === 0) return { error: "no kit guids" };
    const kitStore = (store as any).kit(kitGuids[0]);
    if (!kitStore) return { error: "no kit store" };
    const url = window.location.pathname;
    const designGuidMatch = url.match(/\/designs\/([^/]+)/);
    const designGuid = designGuidMatch?.[1];
    if (!designGuid) return { error: "no design guid in url", url };
    const designGuids = Array.from((kitStore as any).designs?.keys() ?? []) as string[];
    const designStore = kitStore.design(designGuid);
    const hasExecute = designStore && typeof designStore.execute === "function";
    const hasExecuteCommand = designStore && typeof designStore.executeCommand === "function";
    return {
      designGuid,
      designGuids,
      hasDesignStore: !!designStore,
      designStoreType: designStore ? Object.getPrototypeOf(designStore)?.constructor?.name : null,
      hasExecute,
      hasExecuteCommand,
      methods: designStore ? Object.getOwnPropertyNames(Object.getPrototypeOf(designStore)).filter((m: string) => typeof (designStore as any)[m] === "function").slice(0, 20) : [],
    };
  },
  { guids: resolvedConnectionGuids, value: testYValue },
);
console.log(`[Design] DesignStore debug: ${JSON.stringify(designStoreResult)}`);
// Attempt the update
await page.evaluate(
  ({ guids, value }: { guids: string[]; value: number }) => {
    const store = (window as any).__SEMIO_STORE__;
    if (!store) return;
    const kitGuids = Array.from((store as any).kits?.keys() ?? []) as string[];
    if (kitGuids.length === 0) return;
    const kitStore = (store as any).kit(kitGuids[0]);
    if (!kitStore) return;
    const url = window.location.pathname;
    const designGuidMatch = url.match(/\/designs\/([^/]+)/);
    const designGuid = designGuidMatch?.[1];
    if (!designGuid) return;
    const designStore = kitStore.design(designGuid);
    if (!designStore) return;
    // Try executeCommand if execute is not available (class method lookup)
    const fn = designStore.execute || designStore.executeCommand;
    if (typeof fn === "function") {
      fn.call(
        designStore,
        "semio.designApp.updateConnections",
        "semio.sketchpad.test-fallback",
        guids.map((guid: string) => ({ connection: { guid }, diff: { v: value } })),
      );
    }
  },
  { guids: resolvedConnectionGuids, value: testYValue },
);

